-- ************************************** [CONSUMPTION].[vw_ComponentUsage]
CREATE VIEW [CONSUMPTION].[vw_ComponentUsage] AS
SELECT 
    'Offering' AS ParentType,
    o.OfferingId AS ParentId,
    o.OfferingCode AS ParentCode,
    o.OfferingName AS ParentName,
    oi.ItemType,
    CASE 
        WHEN oi.ProductId IS NOT NULL THEN 'Product'
        WHEN oi.ServiceId IS NOT NULL THEN 'Service'
        ELSE 'Unknown'
    END AS ComponentType,
    CASE 
        WHEN oi.ProductId IS NOT NULL THEN (SELECT SKU FROM dbo.Product WHERE ProductId = oi.ProductId)
        WHEN oi.ServiceId IS NOT NULL THEN (SELECT ServiceCode FROM dbo.Service WHERE ServiceId = oi.ServiceId)
        ELSE NULL
    END AS ComponentCode,
    CASE 
        WHEN oi.ProductId IS NOT NULL THEN (SELECT ProductName FROM dbo.Product WHERE ProductId = oi.ProductId)
        WHEN oi.ServiceId IS NOT NULL THEN (SELECT ServiceName FROM dbo.Service WHERE ServiceId = oi.ServiceId)
        ELSE NULL
    END AS ComponentName,
    oi.Quantity,
    oi.SortOrder,
    oi.IsOptional
FROM dbo.OfferingItem oi
INNER JOIN dbo.Offering o ON oi.OfferingId = o.OfferingId

UNION ALL

SELECT 
    'Bundle' AS ParentType,
    b.BundleId AS ParentId,
    b.BundleCode AS ParentCode,
    b.BundleName AS ParentName,
    bi.ItemType,
    CASE 
        WHEN bi.OfferingId IS NOT NULL THEN 'Offering'
        WHEN bi.ChildBundleId IS NOT NULL THEN 'Bundle'
        ELSE 'Unknown'
    END AS ComponentType,
    CASE 
        WHEN bi.OfferingId IS NOT NULL THEN (SELECT OfferingCode FROM dbo.Offering WHERE OfferingId = bi.OfferingId)
        WHEN bi.ChildBundleId IS NOT NULL THEN (SELECT BundleCode FROM dbo.Bundle WHERE BundleId = bi.ChildBundleId)
        ELSE NULL
    END AS ComponentCode,
    CASE 
        WHEN bi.OfferingId IS NOT NULL THEN (SELECT OfferingName FROM dbo.Offering WHERE OfferingId = bi.OfferingId)
        WHEN bi.ChildBundleId IS NOT NULL THEN (SELECT BundleName FROM dbo.Bundle WHERE BundleId = bi.ChildBundleId)
        ELSE NULL
    END AS ComponentName,
    bi.Quantity,
    bi.SortOrder,
    bi.IsOptional
FROM dbo.BundleItem bi
INNER JOIN dbo.Bundle b ON bi.BundleId = b.BundleId;
GO
